# Normas acompanhadas no DOU: um ato que cite qualquer destes marcadores gera alerta
# de "alteração publicada, compilação oficial pendente" para o diploma correspondente.
MARCADORES_DOU = {
  'cf': ['Constituição Federal', 'Emenda Constitucional'],
  'ctn': ['Lei nº 5.172', 'Código Tributário Nacional'],
  'lef': ['Lei nº 6.830'],
  'cpc': ['Lei nº 13.105', 'Código de Processo Civil'],
  'cc': ['Lei nº 10.406', 'Código Civil'],
  'lindb': ['Decreto-Lei nº 4.657'],
  'lcp214': ['Lei Complementar nº 214'],
  'lcp227': ['Lei Complementar nº 227'],
  'lsa': ['Lei nº 6.404'],
  'clt': ['Decreto-Lei nº 5.452', 'Consolidação das Leis do Trabalho'],
  'l8212': ['Lei nº 8.212'],
}
TIPOS_DOU = ['Emenda Constitucional', 'Lei Complementar', 'Lei', 'Medida Provisória', 'Decreto', 'Resolução', 'Instrução Normativa', 'Ato Declaratório']
ORGAOS_DOU = ['Presidência da República', 'Ministério da Fazenda', 'Congresso Nacional', 'Comitê Gestor']


# Todo diploma cadastrado é acompanhado no DOU pelo número da própria norma.
for _d in DIPLOMAS:
    _m = _d['norma'].split(',')[0]
    MARCADORES_DOU.setdefault(_d['id'], [])
    if _m not in MARCADORES_DOU[_d['id']] and not _d['id'] in ('cf', 'adct'):
        MARCADORES_DOU[_d['id']].append(_m)
